    (j: JVal)
    (name: string)
    (dec: JVal -> Result<'T, DecodeError list>)
    (none: unit -> Result<'T, DecodeError list>)
    : Result<'T, DecodeError list> =
    match ov.Absent ov holder name j with
    | Ok None -> none ()
    | Ok(Some v) -> dec v |> cUnder (PathSegment.Key name)
    | Error es -> Error(es |> List.map (DecodeError.under (PathSegment.Key name)))

// A required declared member: absent (and the hook answering `None`) is `dReq`'s refusal.
let private cReqAt (ov: CollectingDecoders) (holder: string) (j: JVal) (name: string) (fs: (string * JVal) list) (dec: JVal -> Result<'T, DecodeError list>) : Result<'T, DecodeError list> =
    match fs |> List.tryFind (fun (k, _) -> k = name) with
    | Some(_, v) -> dec v |> cUnder (PathSegment.Key name)
    | None -> cAbsent ov holder j name dec (fun () -> cOne (dReq name fs (fun _ -> dFail DecodeCode.SchemaFault "never read" "never read")))

let private cOptAt (ov: CollectingDecoders) (holder: string) (j: JVal) (name: string) (fs: (string * JVal) list) (dec: JVal -> Result<'T, DecodeError list>) : Result<'T option, DecodeError list> =
    match fs |> List.tryFind (fun (k, _) -> k = name) with
    | Some(_, v) -> dec v |> cUnder (PathSegment.Key name) |> Result.map Some
    | None -> cAbsent ov holder j name (dec >> Result.map Some) (fun () -> Ok None)

let private cDefAt (ov: CollectingDecoders) (holder: string) (j: JVal) (name: string) (fs: (string * JVal) list) (dec: JVal -> Result<'T, DecodeError list>) (dflt: 'T) : Result<'T, DecodeError list> =
    match fs |> List.tryFind (fun (k, _) -> k = name) with
    | Some(_, v) -> dec v |> cUnder (PathSegment.Key name)
    | None -> cAbsent ov holder j name dec (fun () -> Ok dflt)

// Phase 562 — the generated decoders at the JSON scalars, each the short-circuiting reader lifted.
let private colString (_: CollectingDecoders) (j: JVal) : Result<string, DecodeError list> = cOne (dStr j)

let private colInt (_: CollectingDecoders) (j: JVal) : Result<int, DecodeError list> = cOne (dInt j)

let private colFloat (_: CollectingDecoders) (j: JVal) : Result<float, DecodeError list> = cOne (dFloat j)

let private colBool (_: CollectingDecoders) (j: JVal) : Result<bool, DecodeError list> = cOne (dBool j)

// Phase 562 — the generated `Absent`: every absent member reads by its presence rule.
let private colAbsent (_: CollectingDecoders) (_: string) (_: string) (_: JVal) : Result<JVal option, DecodeError list> = Ok None

let rec private colNodeKind (__ov: CollectingDecoders) (j: JVal) : Result<NodeKind, DecodeError list> =
    cObj j |> Result.bind (fun __fs ->
    dTag __fs |> cOne |> Result.bind (fun __t ->
    match __t with
    | "Grid" -> __ov.GridSpec __ov j |> Result.map NodeKind.Grid
    | "Form" -> __ov.FormSpec __ov j |> Result.map NodeKind.Form
    | __other -> cOne (dUnknown "one of 'Grid', 'Form'" ("$type '" + __other + "'"))))

and private colNode (__ov: CollectingDecoders) (j: JVal) : Result<Node, DecodeError list> =
    cObj j |> Result.bind (fun __fs ->
        let __c0 = cOne (dReq "id" __fs dStr)
        let __c1 = cReq "kind" __fs (colNodeKind __ov)
        match __c0, __c1 with
        | Ok id, Ok kind ->
            Ok { Id = id; Kind = kind }
        | _ -> Error(List.concat [ cErrs __c0; cErrs __c1 ]))

and private colFeed (__ov: CollectingDecoders) (j: JVal) : Result<Feed, DecodeError list> =
    match j with
    | JObj __fs ->
        dTag __fs |> cOne |> Result.bind (fun __t ->
        match __t with
        | "Static" ->
            let __holder = "Feed.Static"
            let __c0 = cReqAt __ov __holder j "value" __fs (cLift dJson)
            match __c0 with
            | Ok value ->
                Ok(Feed.Static(value))
            | _ -> Error(List.concat [ cErrs __c0 ])
        | "State" ->
            let __holder = "Feed.State"
            let __c0 = cReqAt __ov __holder j "key" __fs (__ov.String __ov)
            match __c0 with
            | Ok key ->
                Ok(Feed.State(key))
            | _ -> Error(List.concat [ cErrs __c0 ])
        | __other -> cOne (dUnknown "one of 'Static', 'State'" ("$type '" + __other + "'")))
    | __j -> cOne (Error(Decoder.wrongKind "object" __j))

and private colField (__ov: CollectingDecoders) (j: JVal) : Result<Field, DecodeError list> =
    match j with
    | JObj __fs ->
        dTag __fs |> cOne |> Result.bind (fun __t ->
        match __t with
        | "Text" ->
            let __holder = "Field.Text"
            let __c0 = colMembersTextPayload __ov j __fs
            match __c0 with
            | Ok payload ->
                Ok(Field.Text(payload))
            | _ -> Error(List.concat [ cErrs __c0 ])
        | "Check" ->
            let __holder = "Field.Check"
            let __c0 = cReqAt __ov __holder j "on" __fs (__ov.Bool __ov)
            let __c1 = cOptAt __ov __holder j "label" __fs (__ov.String __ov)
            match __c0, __c1 with
            | Ok on, Ok label ->
                Ok(Field.Check(on, label))
            | _ -> Error(List.concat [ cErrs __c0; cErrs __c1 ])
        | __other -> cOne (dUnknown "one of 'Text', 'Check'" ("$type '" + __other + "'")))
    | __j -> cOne (Error(Decoder.wrongKind "object" __j))

and private colStaticTable (__ov: CollectingDecoders) (j: JVal) : Result<StaticTable, DecodeError list> =
    let __holder = "StaticTable"
    cObj j |> Result.bind (fun __fs ->
        let __c0 = cReqAt __ov __holder j "headers" __fs (cList (__ov.String __ov))
        let __c1 = cReqAt __ov __holder j "rows" __fs (cList (cList (__ov.String __ov)))
        match __c0, __c1 with
        | Ok headers, Ok rows ->
            Ok { Headers = headers; Rows = rows }
        | _ -> Error(List.concat [ cErrs __c0; cErrs __c1 ]))

and private colGridSpec (__ov: CollectingDecoders) (j: JVal) : Result<GridSpec, DecodeError list> =
    let __holder = "GridSpec"
    cObj j |> Result.bind (fun __fs ->
        let __c0 = cReqAt __ov __holder j "columns" __fs (cList (__ov.String __ov))
        let __c1 = colMembersPaging __ov j __fs
        let __c2 = colMembersRowIdentity __ov j __fs
        let __c3 = (colMembersGridRows __ov j __fs |> Result.bind (function Some __v -> Ok __v | None -> Error [ Decoder.missing "source" ]))
        let __c4 = cOptAt __ov __holder j "caption" __fs (__ov.String __ov)
        match __c0, __c1, __c2, __c3, __c4 with
        | Ok columns, Ok paging, Ok identity, Ok rows, Ok caption ->
            Ok { Columns = columns; Paging = paging; Identity = identity; Rows = rows; Caption = caption }
        | _ -> Error(List.concat [ cErrs __c0; cErrs __c1; cErrs __c2; cErrs __c3; cErrs __c4 ]))

and private colFormSpec (__ov: CollectingDecoders) (j: JVal) : Result<FormSpec, DecodeError list> =
    let __holder = "FormSpec"
    cObj j |> Result.bind (fun __fs ->
        let __c0 = cReqAt __ov __holder j "field" __fs (__ov.Field __ov)
        match __c0 with
        | Ok field ->
            Ok { Field = field }
        | _ -> Error(List.concat [ cErrs __c0 ]))

and private colMembersRowIdentity (__ov: CollectingDecoders) (j: JVal) (__fs: (string * JVal) list) : Result<RowIdentity option, DecodeError list> =
    dPick __fs [ ("rowKey", []); ("rowKeyField", []) ] |> cOne |> Result.bind (fun __i ->
    match __i with
    | Some 0 ->
        let __holder = "RowIdentity.RowKey"
        let __c0 = cReqAt __ov __holder j "rowKey" __fs (cLift (dSentinel "<closure>"))
        match __c0 with
        | Ok rowKey ->
            Ok(Some(RowIdentity.RowKey(rowKey)))
        | _ -> Error(List.concat [ cErrs __c0 ])
    | Some 1 ->
        let __holder = "RowIdentity.RowKeyField"
        let __c0 = cReqAt __ov __holder j "rowKeyField" __fs (__ov.String __ov)
        match __c0 with
        | Ok rowKeyField ->
            Ok(Some(RowIdentity.RowKeyField(rowKeyField)))
        | _ -> Error(List.concat [ cErrs __c0 ])
    | _ -> Ok None)

and private colMembersGridRows (__ov: CollectingDecoders) (j: JVal) (__fs: (string * JVal) list) : Result<GridRows option, DecodeError list> =
    dPick __fs [ ("source", []); ("staticRows", [ "source" ]) ] |> cOne |> Result.bind (fun __i ->
    match __i with
    | Some 0 ->
        let __holder = "GridRows.Source"
        let __c0 = cReqAt __ov __holder j "source" __fs (__ov.Feed __ov)
        match __c0 with
        | Ok source ->
            Ok(Some(GridRows.Source(source)))
        | _ -> Error(List.concat [ cErrs __c0 ])
    | Some 1 ->
        let __holder = "GridRows.StaticRows"
        let __c0 = cReqAt __ov __holder j "staticRows" __fs (__ov.StaticTable __ov)
        let __c1 = cOne (dSynth "source" "{\"$type\":\"Static\",\"value\":[]}" __fs)
        match __c0, __c1 with
        | Ok staticRows, Ok () ->
            Ok(Some(GridRows.StaticRows(staticRows)))
        | _ -> Error(List.concat [ cErrs __c0; cErrs __c1 ])
    | _ -> Ok None)

and private colMembersPaging (__ov: CollectingDecoders) (j: JVal) (__fs: (string * JVal) list) : Result<Paging, DecodeError list> =
    let __holder = "Paging"
    let __c0 = cOptAt __ov __holder j "pageSize" __fs (__ov.Int __ov)
    let __c1 = cOptAt __ov __holder j "pageStateKey" __fs (__ov.String __ov)
    match __c0, __c1 with
    | Ok pageSize, Ok pageStateKey ->
        Ok { PageSize = pageSize; PageStateKey = pageStateKey }
    | _ -> Error(List.concat [ cErrs __c0; cErrs __c1 ])

and private colMembersTextPayload (__ov: CollectingDecoders) (j: JVal) (__fs: (string * JVal) list) : Result<TextPayload, DecodeError list> =
    let __holder = "TextPayload"
    let __c0 = cReqAt __ov __holder j "value" __fs (__ov.String __ov)
    let __c1 = cOptAt __ov __holder j "placeholder" __fs (__ov.String __ov)
    match __c0, __c1 with
    | Ok value, Ok placeholder ->
        Ok { Value = value; Placeholder = placeholder }
    | _ -> Error(List.concat [ cErrs __c0; cErrs __c1 ])

/// Phase 541 — the generated collecting decoders: what every `decode*All` entry reads through, and
/// the record a host copies (`{ collectingDecoders with <Type> = … }`) to override one type.
let collectingDecoders: CollectingDecoders =
    { Node = colNode
      Feed = colFeed
      Field = colField
      StaticTable = colStaticTable
      GridSpec = colGridSpec
      FormSpec = colFormSpec
      String = colString
      Int = colInt
      Float = colFloat
      Bool = colBool
      Absent = colAbsent }

/// Phase 377 — the public per-spec decoders. `decode<Tag>Spec` reads one kind's object and
/// answers its FIRST defect; `decode<Tag>SpecAll` reads the same object and answers EVERY defect,
/// in the order stated above the collecting prelude. A consumer delegates one kind at a time.
/// Phase 541 — `decode<Tag>SpecAllWith` reads it through a host's `CollectingDecoders`, so the
/// host's decoder at a type applies at every depth; `decode<Tag>SpecAll` is its no-override case.
let decodeGridSpec (j: JVal) : Result<GridSpec, DecodeError> = decGridSpec j
let decodeGridSpecAll (j: JVal) : Result<GridSpec, DecodeError list> = colGridSpec collectingDecoders j
let decodeGridSpecAllWith (decoders: CollectingDecoders) (j: JVal) : Result<GridSpec, DecodeError list> =
    decoders.GridSpec decoders j
let decodeFormSpec (j: JVal) : Result<FormSpec, DecodeError> = decFormSpec j
let decodeFormSpecAll (j: JVal) : Result<FormSpec, DecodeError list> = colFormSpec collectingDecoders j
let decodeFormSpecAllWith (decoders: CollectingDecoders) (j: JVal) : Result<FormSpec, DecodeError list> =
    decoders.FormSpec decoders j
/// The whole node over a parsed value: the first defect, or every defect.
let decodeNodeJson (j: JVal) : Result<Node, DecodeError> = decNode j
let decodeNodeJsonAll (j: JVal) : Result<Node, DecodeError list> = colNode collectingDecoders j
let decodeNodeJsonAllWith (decoders: CollectingDecoders) (j: JVal) : Result<Node, DecodeError list> =
    decoders.Node decoders j
/// `decodeNode`'s collecting twin: a parser refusal is the one defect, else every defect.
let decodeNodeAll (s: string) : Result<Node, DecodeError list> =
    Decoder.parse ReadOptions.strict s |> cOne |> Result.bind (colNode collectingDecoders)
let decodeNodeAllWith (decoders: CollectingDecoders) (s: string) : Result<Node, DecodeError list> =
    Decoder.parse ReadOptions.strict s |> cOne |> Result.bind (decoders.Node decoders)